import React, { useEffect, useRef, useState } from 'react';
import MemberBubble from '../ui/MemberBubble';
import { Compass, Radio } from 'lucide-react';

// Theme system - ready for future additions like snowflakes
const RADAR_THEMES = {
  default: {
    name: 'Default',
    particles: null, // Can add snowflakes, stars, etc. here
  },
  snowglobe: {
    name: 'Snowglobe',
    particles: 'snowflakes', // Future: snowflakes falling
  },
};

// Geographic calculation utilities for radar positioning
const calculateBearing = (lat1, lon1, lat2, lon2) => {
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const lat1Rad = lat1 * Math.PI / 180;
  const lat2Rad = lat2 * Math.PI / 180;

  const y = Math.sin(dLon) * Math.cos(lat2Rad);
  const x = Math.cos(lat1Rad) * Math.sin(lat2Rad) - 
            Math.sin(lat1Rad) * Math.cos(lat2Rad) * Math.cos(dLon);

  let bearing = Math.atan2(y, x);
  bearing = bearing * 180 / Math.PI;
  bearing = (bearing + 360) % 360;

  return bearing;
};

const calculateDistance = (lat1, lon1, lat2, lon2) => {
  const R = 6371; // Earth's radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c; // Distance in km
};

const BubbleCluster = ({ bubbleData, onStatusClick, onMemberClick, theme = 'default' }) => {
  const clusterRef = useRef(null);
  const canvasRef = useRef(null);

  const [nodes, setNodes] = useState([]);
  const [positions, setPositions] = useState({});
  const [maxDistance, setMaxDistance] = useState(100); // km
  const [sweepAngle, setSweepAngle] = useState(0);

  // Ensure currentMember and allMembers are safely accessed
  const currentMember = bubbleData?.currentMember;
  const allMembers = bubbleData?.allMembers || [];

  // Filter and prepare members - ensure they have required properties
  const validMembers = allMembers.filter(member => {
    if (!member || typeof member !== 'object') return false;
    const memberId = member.id || member.nodeId;
    if (!memberId) return false;
    if (!member.id && member.nodeId) {
      member.id = member.nodeId;
    }
    return true;
  });

  const memberIdString = validMembers.map(m => m.id).join(',');

  /** ----------------------------
   * RADAR POSITIONING BASED ON LOCATION
   * ---------------------------- */
  useEffect(() => {
    if (!currentMember || !validMembers.length) {
      return;
    }

    const container = clusterRef.current;
    if (!container) return;

    const width = container.offsetWidth;
    const height = container.offsetHeight;
    const centerX = width / 2;
    const centerY = height / 2;
    const maxRadius = Math.min(width, height) * 0.4;

    const centerLocation = currentMember.lastKnownLocation;
    if (!centerLocation || !centerLocation.latitude || !centerLocation.longitude) {
      // Fallback to tier-based if no location
      const ownerNode = validMembers.find(m => m.type === 'owner' || m.tier === 1);
      const tierGroups = {};
      validMembers.forEach(member => {
        const tier = member.tier || (member.type === 'owner' ? 1 : 2);
        if (!tierGroups[tier]) tierGroups[tier] = [];
        tierGroups[tier].push(member);
      });

      const fallbackNodes = validMembers.map((member) => {
        const isOwner = member.type === 'owner' || member.tier === 1;
        const tier = member.tier || (isOwner ? 1 : 2);

        let x, y;
        if (isOwner || (ownerNode && member.id === ownerNode.id)) {
          x = centerX;
          y = centerY;
        } else {
          const tierRadius = {
            1: 0,
            2: maxRadius * 0.5,
            3: maxRadius * 0.7,
            4: maxRadius * 0.9,
          };
          const radius = tierRadius[tier] || tierRadius[4];
          const membersInTier = tierGroups[tier] || [];
          const tierIndex = membersInTier.findIndex(m => m.id === member.id);
          const angle = (tierIndex / Math.max(membersInTier.length, 1)) * Math.PI * 2;
          x = centerX + Math.cos(angle) * radius;
          y = centerY + Math.sin(angle) * radius;
        }

        return {
          id: member.id,
          ...member,
          x,
          y,
          distance: 0,
          bearing: 0,
        };
      });

      setNodes(fallbackNodes);
      const initialPositions = {};
      fallbackNodes.forEach(n => {
        initialPositions[n.id] = { x: n.x, y: n.y };
      });
      setPositions(initialPositions);
      return;
    }

    // Calculate positions based on geographic location
    const centerLat = centerLocation.latitude;
    const centerLon = centerLocation.longitude;

    const membersWithLocation = validMembers
      .map(member => {
        const loc = member.lastKnownLocation;
        if (!loc || !loc.latitude || !loc.longitude) return null;

        const distance = calculateDistance(centerLat, centerLon, loc.latitude, loc.longitude);
        const bearing = calculateBearing(centerLat, centerLon, loc.latitude, loc.longitude);

        return {
          member,
          distance,
          bearing,
        };
      })
      .filter(Boolean);

    const distances = membersWithLocation.map(m => m.distance);
    const calculatedMaxDistance = Math.max(...distances, 10);
    setMaxDistance(calculatedMaxDistance);

    const radarNodes = validMembers.map((member) => {
      const isCurrentUser = member.id === currentMember.id;

      if (isCurrentUser) {
        return {
          id: member.id,
          ...member,
          x: centerX,
          y: centerY,
          distance: 0,
          bearing: 0,
        };
      }

      const locationData = membersWithLocation.find(m => m.member.id === member.id);

      if (locationData) {
        const normalizedDistance = Math.min(locationData.distance / calculatedMaxDistance, 1);
        const radius = normalizedDistance * maxRadius;
        const angleRad = ((locationData.bearing - 90) * Math.PI / 180);

        const x = centerX + Math.cos(angleRad) * radius;
        const y = centerY + Math.sin(angleRad) * radius;

        return {
          id: member.id,
          ...member,
          x,
          y,
          distance: locationData.distance,
          bearing: locationData.bearing,
        };
      } else {
        const angle = Math.random() * Math.PI * 2;
        const radius = maxRadius * 0.9;
        return {
          id: member.id,
          ...member,
          x: centerX + Math.cos(angle) * radius,
          y: centerY + Math.sin(angle) * radius,
          distance: null,
          bearing: null,
        };
      }
    });

    setNodes(radarNodes);

    const initialPositions = {};
    radarNodes.forEach(n => {
      initialPositions[n.id] = { x: n.x, y: n.y };
    });
    setPositions(initialPositions);
  }, [memberIdString, currentMember, validMembers.length, validMembers]);

  /** ----------------------------
   * ANIMATED RADAR SWEEP
   * ---------------------------- */
  useEffect(() => {
    const sweepInterval = setInterval(() => {
      setSweepAngle(prev => (prev + 1.5) % 360);
    }, 30);

    return () => clearInterval(sweepInterval);
  }, []);

  if (!currentMember) {
    return (
      <div className="flex items-center justify-center w-full h-full">
        <div className="text-center space-y-3">
          <div className="w-12 h-12 border-4 border-t-transparent border-purple-500 rounded-full animate-spin mx-auto glow-purple"></div>
          <p className="text-gray-300 font-semibold">Loading your bubble...</p>
        </div>
      </div>
    );
  }

  const container = clusterRef.current;
  const containerWidth = container?.offsetWidth || 500;
  const containerHeight = container?.offsetHeight || 500;
  const centerX = containerWidth / 2;
  const centerY = containerHeight / 2;
  const radarRadius = Math.min(containerWidth, containerHeight) / 2;

  return (
    <div className="flex items-center justify-center w-full h-full relative">
      {/* Outer radar frame with glow */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <div className="w-[min(600px,90vw)] h-[min(600px,90vw)] rounded-full border-2 border-cyan-400/40 shadow-[0_0_60px_rgba(34,211,238,0.4),0_0_120px_rgba(34,211,238,0.2),inset_0_0_40px_rgba(34,211,238,0.1)] radar-glow"></div>
        <div className="absolute w-[min(580px,87vw)] h-[min(580px,87vw)] rounded-full border border-blue-400/30"></div>
      </div>

      {/* Main radar container */}
      <div
        className="relative w-[min(500px,75vw)] h-[min(500px,75vw)] rounded-full overflow-visible"
        ref={clusterRef}
        style={{
          background: 'radial-gradient(circle, rgba(15, 23, 42, 0.95) 0%, rgba(2, 6, 23, 0.98) 100%)',
        }}
      >
        {/* Radar grid - radial lines (N, E, S, W and diagonals) */}
        <div className="absolute inset-0 rounded-full pointer-events-none">
          {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => (
            <div
              key={angle}
              className="absolute top-1/2 left-1/2 origin-top"
              style={{
                transform: `translate(-50%, -50%) rotate(${angle}deg)`,
                width: '2px',
                height: '50%',
                background: angle % 90 === 0 
                  ? 'linear-gradient(to bottom, rgba(34, 211, 238, 0.4) 0%, rgba(34, 211, 238, 0.1) 50%, transparent 100%)'
                  : 'linear-gradient(to bottom, rgba(59, 130, 246, 0.2) 0%, rgba(59, 130, 246, 0.05) 50%, transparent 100%)',
                boxShadow: angle % 90 === 0 
                  ? '0 0 4px rgba(34, 211, 238, 0.3)' 
                  : '0 0 2px rgba(59, 130, 246, 0.2)',
              }}
            />
          ))}
        </div>

        {/* Enhanced concentric radar rings - inner rings more prominent */}
        {[1, 2, 3, 4, 5].map((ring) => {
          const ringSize = (ring / 5) * 90;
          // Inner rings are brighter and more visible
          const isInnerRing = ring <= 2;
          const ringOpacity = isInnerRing 
            ? 0.7 - (ring * 0.15)  // Inner rings: 0.7, 0.55
            : 0.4 - ((ring - 2) * 0.08); // Outer rings: 0.4, 0.32, 0.24
          const borderWidth = isInnerRing ? '2px' : '1.5px';
          const glowIntensity = isInnerRing ? 1.2 : 0.6;

          return (
            <div
              key={ring}
              className="absolute rounded-full pointer-events-none radar-ring-pulse"
              style={{
                width: `${ringSize}%`,
                height: `${ringSize}%`,
                left: '50%',
                top: '50%',
                transform: 'translate(-50%, -50%)',
                border: `${borderWidth} solid rgba(34, 211, 238, ${ringOpacity})`,
                borderRadius: '50%',
                boxShadow: `
                  0 0 ${(8 + ring * 2) * glowIntensity}px rgba(34, 211, 238, ${ringOpacity * glowIntensity}),
                  0 0 ${(4 + ring) * glowIntensity}px rgba(59, 130, 246, ${ringOpacity * glowIntensity * 0.7}),
                  inset 0 0 ${(4 + ring)}px rgba(34, 211, 238, ${ringOpacity * 0.4})
                `,
                animationDelay: `${ring * 0.25}s`,
              }}
            />
          );
        })}

        {/* Additional inner highlight rings for depth */}
        {[1, 2].map((ring) => (
          <div
            key={`highlight-${ring}`}
            className="absolute rounded-full pointer-events-none"
            style={{
              width: `${(ring / 5) * 90}%`,
              height: `${(ring / 5) * 90}%`,
              left: '50%',
              top: '50%',
              transform: 'translate(-50%, -50%)',
              border: `0.5px solid rgba(255, 255, 255, ${0.2 - ring * 0.05})`,
              borderRadius: '50%',
              boxShadow: `inset 0 0 ${3 + ring}px rgba(255, 255, 255, ${0.1 - ring * 0.02})`,
            }}
          />
        ))}

        {/* Distance markers on rings (North position) */}
        {[1, 2, 3, 4, 5].map((ring) => {
          const ringSize = (ring / 5) * 90;
          const markerDistance = (ringSize / 2) * (containerWidth / 100);
          const isInnerRing = ring <= 2;

          return (
            <div
              key={`marker-${ring}`}
              className="absolute pointer-events-none"
              style={{
                left: '50%',
                top: `${50 - (ringSize / 2)}%`,
                transform: 'translate(-50%, -50%)',
                width: '4px',
                height: isInnerRing ? '8px' : '6px',
                background: `linear-gradient(to bottom, rgba(34, 211, 238, ${isInnerRing ? 0.9 : 0.6}), rgba(34, 211, 238, ${isInnerRing ? 0.5 : 0.3}))`,
                borderRadius: '2px',
                boxShadow: `0 0 ${isInnerRing ? 6 : 4}px rgba(34, 211, 238, ${isInnerRing ? 0.8 : 0.5})`,
              }}
            />
          );
        })}

        {/* Compass directions - enhanced styling */}
        {[
          { dir: 'N', angle: 0, pos: 'top-2' },
          { dir: 'NE', angle: 45, pos: 'top-2 right-2' },
          { dir: 'E', angle: 90, pos: 'right-2' },
          { dir: 'SE', angle: 135, pos: 'bottom-2 right-2' },
          { dir: 'S', angle: 180, pos: 'bottom-2' },
          { dir: 'SW', angle: 225, pos: 'bottom-2 left-2' },
          { dir: 'W', angle: 270, pos: 'left-2' },
          { dir: 'NW', angle: 315, pos: 'top-2 left-2' },
        ].map(({ dir, pos }) => (
          <div key={dir} className={`absolute ${pos} transform -translate-x-1/2 -translate-y-1/2 pointer-events-none`}>
            <div className="text-cyan-400/80 text-[10px] font-bold glass-light px-1.5 py-0.5 rounded border border-cyan-400/20 shadow-[0_0_8px_rgba(34,211,238,0.3)]">
              {dir}
            </div>
          </div>
        ))}

        {/* Enhanced radar sweep line with trailing effect */}
        <div className="absolute top-1/2 left-1/2 pointer-events-none" style={{ transformOrigin: 'center bottom' }}>
          {/* Main sweep line */}
          <div
            className="absolute"
            style={{
              transform: `translate(-50%, -50%) rotate(${sweepAngle}deg)`,
              width: '3px',
              height: '50%',
              background: 'linear-gradient(to bottom, rgba(34, 211, 238, 1) 0%, rgba(59, 130, 246, 0.8) 30%, rgba(59, 130, 246, 0.4) 60%, transparent 100%)',
              transformOrigin: 'center bottom',
              boxShadow: '0 0 12px rgba(34, 211, 238, 0.8), 0 0 24px rgba(34, 211, 238, 0.4)',
              borderRadius: '2px',
            }}
          />
          {/* Trailing sweep effect */}
          <div
            className="absolute"
            style={{
              transform: `translate(-50%, -50%) rotate(${sweepAngle - 15}deg)`,
              width: '2px',
              height: '50%',
              background: 'linear-gradient(to bottom, rgba(34, 211, 238, 0.4) 0%, rgba(59, 130, 246, 0.2) 30%, transparent 100%)',
              transformOrigin: 'center bottom',
              boxShadow: '0 0 8px rgba(34, 211, 238, 0.3)',
              borderRadius: '1px',
            }}
          />
        </div>

        {/* Enhanced center crosshair */}
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 pointer-events-none">
          {/* Outer crosshair */}
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
            <div className="w-12 h-0.5 bg-cyan-400/60 shadow-[0_0_4px_rgba(34,211,238,0.5)]"></div>
            <div className="h-12 w-0.5 bg-cyan-400/60 absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 shadow-[0_0_4px_rgba(34,211,238,0.5)]"></div>
          </div>
          {/* Inner crosshair */}
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2">
            <div className="w-6 h-0.5 bg-blue-500/80"></div>
            <div className="h-6 w-0.5 bg-blue-500/80 absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2"></div>
          </div>
          {/* Center dot */}
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full border-2 border-cyan-400/90 bg-cyan-400/30 shadow-[0_0_12px_rgba(34,211,238,0.6),inset_0_0_8px_rgba(34,211,238,0.3)] radar-pulse"></div>
        </div>

        {/* Subtle radar background texture */}
        <div 
          className="absolute inset-0 rounded-full pointer-events-none"
          style={{
            background: `
              radial-gradient(circle at 30% 30%, rgba(34, 211, 238, 0.08) 0%, transparent 40%),
              radial-gradient(circle at 70% 70%, rgba(59, 130, 246, 0.06) 0%, transparent 40%),
              repeating-conic-gradient(from 0deg at 50% 50%, transparent 0deg, rgba(34, 211, 238, 0.02) 1deg, transparent 2deg)
            `,
            opacity: 0.6,
          }}
        />

        {/* Grid overlay for radar feel */}
        <div 
          className="absolute inset-0 rounded-full pointer-events-none"
          style={{
            backgroundImage: `
              linear-gradient(rgba(34, 211, 238, 0.1) 1px, transparent 1px),
              linear-gradient(90deg, rgba(34, 211, 238, 0.1) 1px, transparent 1px)
            `,
            backgroundSize: '20px 20px',
            opacity: 0.3,
            maskImage: 'radial-gradient(circle, black 85%, transparent 100%)',
            WebkitMaskImage: 'radial-gradient(circle, black 85%, transparent 100%)',
          }}
        />

        {/* Glassmorphic overlay */}
        <div className="absolute inset-0 rounded-full glass-light pointer-events-none"></div>

        {/* Member bubbles positioned by location */}
        {nodes.map((node, index) => {
          const pos = positions[node.id] || { x: node.x, y: node.y };
          const isCurrentUser = node.id === currentMember.id;

          const leftPercent = ((pos?.x ?? node.x ?? centerX) / containerWidth) * 100;
          const topPercent = ((pos?.y ?? node.y ?? centerY) / containerHeight) * 100;

          return (
            <div
              key={node.id}
              className="member-bubble-wrapper absolute"
              style={{
                left: `${leftPercent}%`,
                top: `${topPercent}%`,
                transform: `translate(-50%, -50%)`,
                transition: 'left 0.4s cubic-bezier(0.4, 0, 0.2, 1), top 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                zIndex: isCurrentUser ? 20 : 10,
              }}
            >
              <MemberBubble
                member={node}
                isCenter={isCurrentUser}
                onClick={isCurrentUser ? onStatusClick : () => onMemberClick && onMemberClick(node)}
                delay={index * 50}
                position={pos}
              />
            </div>
          );
        })}

        {/* Radar center glow effects */}
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-40 h-40 bg-gradient-to-r from-cyan-500/20 via-blue-500/15 to-cyan-500/20 rounded-full blur-3xl pointer-events-none radar-pulse"></div>
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-28 h-28 bg-cyan-500/25 rounded-full blur-2xl pointer-events-none"></div>
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-16 h-16 bg-cyan-400/30 rounded-full blur-xl pointer-events-none"></div>
      </div>

      {/* Radar info overlay - enhanced styling */}
      <div className="absolute bottom-4 left-4 glass-light rounded-xl px-3 py-2 border border-cyan-400/20 shadow-lg backdrop-blur-md">
        <div className="flex items-center gap-2">
          <Radio className="w-4 h-4 text-cyan-400" />
          <div>
            <p className="text-xs text-gray-200 font-semibold">Radar Active</p>
            <p className="text-xs text-cyan-400/90 font-mono">
              {maxDistance < 1 
                ? `${(maxDistance * 1000).toFixed(0)}m` 
                : maxDistance < 1000
                ? `${maxDistance.toFixed(1)}km`
                : `${(maxDistance / 1000).toFixed(1)}k km`}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BubbleCluster;
